mapper.sql:
/*채팅 data WITH구문*/ WITH YB20 AS( SELECT CHRO_NO /*채팅방번호*/ FROM AYB200 /*채팅이력*/ WHERE AYB200.SXDC_SE_CD LIKE #{gender} /*성별*/ /*회원을 선택한 경우*/
AND EXISTS (SELECT 'Y' /*회원*/ FROM SAA200 WHERE USER_ID = AYB200.CNSLTNT_ID OR ENFSN_NO = AYB200.CNSLTNT_ID OR YNGBGS_PRTCR_NO = AYB200.CNSLTNT_ID )
/*비회원을 선택한 경우*/
AND NOT EXISTS (SELECT 'Y' /*비회원*/ FROM SAA200 WHERE USER_ID = AYB200.CNSLTNT_ID OR ENFSN_NO = AYB200.CNSLTNT_ID OR YNGBGS_PRTCR_NO = AYB200.CNSLTNT_ID )
AND AYB200.DEL_YN = 'N' AND FRST_REG_DT BETWEEN TO_DATE(#{startDate}, 'YYYYMMDD') AND TO_DATE(#{endDate}, 'YYYYMMDD') + 0.99999 ) , YE15 AS( SELECT AYE195.MSRMT_SCORE AS SCORE , AYE195.INDEX_SN AS INDEX_SN FROM AYE195 /*상담글평가*/ , YB20 WHERE AYE195.BBSCTT_ESNTAL_NO = YB20.CHRO_NO /*채팅방번호*/ AND AYE195.DEL_YN = 'N' )

mapper.select:
/*전체*/
SELECT /*SQL-ID :isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper." : selectconQuestionStats*/
SUM(YE15.SCORE) / 8 AS AVG , CASE WHEN RSPNS_CN = '1' THEN COUNT(1) ELSE 0 END AS L1 , CASE WHEN RSPNS_CN = '2' THEN COUNT(1) ELSE 0 END AS L2 , CASE WHEN RSPNS_CN = '3' THEN COUNT(1) ELSE 0 END AS L3 , CASE WHEN RSPNS_CN = '4' THEN COUNT(1) ELSE 0 END AS L4 , CASE WHEN RSPNS_CN = '5' THEN COUNT(1) ELSE 0 END AS L5 , CASE WHEN RSPNS_CN = '6' THEN COUNT(1) ELSE 0 END AS L6 , CASE WHEN RSPNS_CN = '7' THEN COUNT(1) ELSE 0 END AS L7 , CASE WHEN RSPNS_CN = '8' THEN COUNT(1) ELSE 0 END AS L8 , CASE WHEN RSPNS_CN = '9' THEN COUNT(1) ELSE 0 END AS L9 , CASE WHEN RSPNS_CN = '10' THEN COUNT(1) ELSE 0 END AS L10 , COUNT(AYE196.RSPNS_CN) OVER() AS TOTAL FROM AYE196 , YE15 WHERE AYE196.INDEX_SN = YE15.INDEX_SN AND AYE196.DEL_YN = 'N' AND AYE196.QESITM_ESNTAL_NO IS NOT NULL GROUP BY RSPNS_CN

/*1번*/
