SUM(YE15.SCORE) / 8 AS AVG , CASE WHEN RSPNS_CN = '1' THEN COUNT(1) ELSE 0 END AS L1 , CASE WHEN RSPNS_CN = '2' THEN COUNT(1) ELSE 0 END AS L2 , CASE WHEN RSPNS_CN = '3' THEN COUNT(1) ELSE 0 END AS L3 , CASE WHEN RSPNS_CN = '4' THEN COUNT(1) ELSE 0 END AS L4 , CASE WHEN RSPNS_CN = '5' THEN COUNT(1) ELSE 0 END AS L5 , CASE WHEN RSPNS_CN = '6' THEN COUNT(1) ELSE 0 END AS L6 , CASE WHEN RSPNS_CN = '7' THEN COUNT(1) ELSE 0 END AS L7 , CASE WHEN RSPNS_CN = '8' THEN COUNT(1) ELSE 0 END AS L8 , CASE WHEN RSPNS_CN = '9' THEN COUNT(1) ELSE 0 END AS L9 , CASE WHEN RSPNS_CN = '10' THEN COUNT(1) ELSE 0 END AS L10 , COUNT(AYE196.RSPNS_CN) OVER() AS TOTAL FROM AYE196 , YE15 WHERE AYE196.INDEX_SN = YE15.INDEX_SN AND AYE196.DEL_YN = 'N' AND AYE196.QESITM_ESNTAL_NO = '1' GROUP BY RSPNS_CN

