/*채팅평균대기시간*/
SELECT /*SQL-ID :isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper." : selectconQuestionStatsChatWaitAvg*/
SUM(MIN * MCOUNT) / SUM(MCOUNT) AS AVG FROM ( SELECT ROUND((AYB230.WAIT_DT - AYB230.BGNG_DT) * 24 * 60, 0) AS MIN , COUNT(AYB230.CHRO_NO) AS MCOUNT FROM AYB230 , YB20 WHERE AYB230.CHRO_NO = YB20.CHRO_NO GROUP BY ROUND((AYB230.WAIT_DT - AYB230.BGNG_DT) * 24 * 60, 0) ORDER BY 1 ) A

/*채팅대기시간*/
SELECT /*SQL-ID :isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper." : selectconQuestionStatsChatWait*/
ROUND((AYB230.WAIT_DT - AYB230.BGNG_DT) * 24 * 60, 0) AS MIN , COUNT(AYB230.CHRO_NO) AS MCOUNT FROM AYB230 , YB20 WHERE AYB230.CHRO_NO = YB20.CHRO_NO GROUP BY ROUND((AYB230.WAIT_DT - AYB230.BGNG_DT) * 24 * 60, 0) ORDER BY 1

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectCnctDscsnStatsList - 응용2팀 지원 정원제 */ SELECT AA.CD AACD, /* 이음게시판카테고리구분코드 */ BB.NO BBNO, /* 회기관리번호 */ AA.NM NM, /* 이음e구분명 */ AA.SESN_MNG_NM SESN_MNG_NM, /* 회기 */ AA.CNT CNT, /* 총수 */ AA.MCNT MCNT, /* 남자 */ AA.FCNT FCNT, /* 여자 */ AA.XCNT XCNT, /* 성별미확인 */ BB.CNT BBCNT, /* 답글수 */ BB.MCNT BBMCNT, /* 답글 남자 건수 */ BB.FCNT BBFCNT, /* 답글 여자 건수 */ BB.XCNT BBXCNT /* 답글 미확인 건수 */ FROM ( SELECT A.CNCT_NTABRD_CTGRYB_SE_CD CD, A.SESN_MNG_NO NO, MAX(C.CMMNS_CD_VALUE_NM) NM, CASE WHEN A.SESN_MNG_NO = '1' THEN MAX(C.ADDTNG_MNG_VALUE1 ) WHEN A.SESN_MNG_NO = '2' THEN MAX(C.ADDTNG_MNG_VALUE2 ) WHEN A.SESN_MNG_NO = '3' THEN MAX(C.ADDTNG_MNG_VALUE3 ) WHEN A.SESN_MNG_NO = '4' THEN MAX(C.ADDTNG_MNG_VALUE4 ) ELSE '' END SESN_MNG_NM, COUNT(*) CNT, SUM(CASE WHEN A.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END) MCNT, SUM(CASE WHEN A.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END) FCNT, SUM(CASE WHEN A.SXDC_SE_CD IS NULL THEN 1 ELSE 0 END) XCNT FROM AYE100 A , SAC100 C WHERE 1=1 AND A.BBSCTT_TYPE_SE_CD = #{bbscttTypeSeCd}
AND A.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{endDate} || '000000', 'YYYYMMDDHH24MISS')
AND C.CMMNS_CD_ID = 'CNCT_NTABRD_CTGRYB_SE_CD' AND CMMNS_CD_VALUE = A.CNCT_NTABRD_CTGRYB_SE_CD AND A.DEL_YN = 'N' AND C.USE_YN = 'Y' GROUP BY A.CNCT_NTABRD_CTGRYB_SE_CD, A.SESN_MNG_NO ) AA, ( SELECT A.CNCT_NTABRD_CTGRYB_SE_CD CD, A.SESN_MNG_NO NO, SUM(CASE WHEN B.BBSCTT_ESNTAL_NO IS NULL THEN 0 ELSE 1 END) CNT, SUM(CASE WHEN D.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END) MCNT, SUM(CASE WHEN D.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END) FCNT, SUM(CASE WHEN D.SXDC_SE_CD IS NULL THEN 1 ELSE 0 END) XCNT FROM AYE100 A , AYE110 B , SAA200 C , SCA100 D WHERE 1=1 AND A.BBSCTT_TYPE_SE_CD = #{bbscttTypeSeCd} AND A.BBSCTT_ESNTAL_NO = B.BBSCTT_ESNTAL_NO(+) AND A.BBSCTT_TYPE_SE_CD = B.BBSCTT_TYPE_SE_CD(+)
AND A.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{endDate} || '000000', 'YYYYMMDDHH24MISS')
AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' AND C.USER_ID = B.FRST_RGTR_ID AND D.ENFSN_NO = C.ENFSN_NO GROUP BY A.CNCT_NTABRD_CTGRYB_SE_CD, A.SESN_MNG_NO ) BB WHERE AA.CD = BB.CD AND AA.NO = BB.NO ORDER BY AA.CD, BB.NO

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectSlrbyDgstfnStatsNewList1 - 개발지원팀 이태호 */
/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectSlrbyDgstfnStatsNewList1 - 김해룡 */
SELECT AA.CMMNS_CD_VALUE, AA.CMMNS_CD_VALUE_NM, nvl(BB.CNT,0) AS CNT FROM ( SELECT CMMNS_CD_VALUE, UP_CMMNS_CD_VALUE, CMMNS_CD_VALUE_NM FROM SAC100 WHERE 1=1 AND CMMNS_CD_ID = 'SLRBT_DSCSN_SCLAS_SE_CD' AND UP_CMMNS_CD_VALUE < '100' ) AA, ( SELECT A.SLRBT_DSCSN_SCLAS_SE_CD, COUNT(*) CNT FROM AYE100 A, AYE195 B WHERE 1=1 AND A.BBSCTT_TYPE_SE_CD IN ('01','02') AND A.BBSCTT_ESNTAL_NO = B.BBSCTT_ESNTAL_NO AND A.BBSCTT_TYPE_SE_CD = B.BBSCTT_TYPE_SE_CD AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' AND B.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT < TO_DATE(#{endDate} || '235959', 'YYYYMMDDHH24MISS') GROUP BY A.SLRBT_DSCSN_SCLAS_SE_CD ) BB WHERE AA.CMMNS_CD_VALUE = BB.SLRBT_DSCSN_SCLAS_SE_CD(+)

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectSlrbyDgstfnStatsNewList2 - 개발지원팀 이태호 */
/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectSlrbyDgstfnStatsNewList2 - 김해룡 */
SELECT AA.CMMNS_CD_VALUE, AA.CMMNS_CD_VALUE_NM, nvl(BB.CNT,0) AS CNT FROM ( SELECT CMMNS_CD_VALUE, UP_CMMNS_CD_VALUE, CMMNS_CD_VALUE_NM FROM SAC100 WHERE 1=1 AND CMMNS_CD_ID = 'SLRBT_DSCSN_SCLAS_SE_CD' AND UP_CMMNS_CD_VALUE > '100' ) AA, ( SELECT A.SLRBT_DSCSN_SCLAS_SE_CD, COUNT(*) CNT FROM AYE100 A, AYE195 B WHERE 1=1 AND A.BBSCTT_TYPE_SE_CD IN ('01','02') AND A.BBSCTT_ESNTAL_NO = B.BBSCTT_ESNTAL_NO AND A.BBSCTT_TYPE_SE_CD = B.BBSCTT_TYPE_SE_CD AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' AND B.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT < TO_DATE(#{endDate} || '235959', 'YYYYMMDDHH24MISS') GROUP BY A.SLRBT_DSCSN_SCLAS_SE_CD ) BB WHERE AA.CMMNS_CD_VALUE = BB.SLRBT_DSCSN_SCLAS_SE_CD(+)

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectGriefSltnAlkiolDgstfnStatsList - 응용2팀 지원 정원제 */ SELECT AA.SN AS GRIEF_SLTN_ALKIOL_SN, AA.NM AS TTL_NM, NVL(BB.CNT,0) AS TOT_CNT FROM ( SELECT GRIEF_SLTN_ALKIOL_SN AS SN, TTL_NM AS NM FROM AYE410 ORDER BY GRIEF_SLTN_ALKIOL_THMA_SN, SQNCE_NO ) AA, ( SELECT A.GRIEF_SLTN_ALKIOL_SN AS SN, COUNT(*) AS CNT FROM AYE100 A , AYE195 B WHERE 1=1 AND A.BBSCTT_TYPE_SE_CD = #{bbscttTypeSeCd} AND A.BBSCTT_ESNTAL_NO = B.BBSCTT_ESNTAL_NO AND A.BBSCTT_TYPE_SE_CD = B.BBSCTT_TYPE_SE_CD
AND B.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT <= TO_DATE(#{endDate} || '000000', 'YYYYMMDDHH24MISS')
AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' GROUP BY A.GRIEF_SLTN_ALKIOL_SN ) BB WHERE AA.SN = BB.SN(+)


/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectWeposInspStatsList1 - 개발지원팀 이태호 */
SELECT 'aaa' AS aaa
  FROM AYE100 a /* 사이버상담게시글 */
 WHERE 1=1           
   AND a.DEL_YN = 'N'
   AND a.FRST_REG_DT BETWEEN  #{startDate} AND #{endDate}


/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectWeposInspStatsList2 - 개발지원팀 이태호 */
SELECT 'aaa' AS aaa
  FROM AYE100 a /* 사이버상담게시글 */
 WHERE 1=1           
   AND a.DEL_YN = 'N'
   AND a.FRST_REG_DT BETWEEN  #{startDate} AND #{endDate}

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectSlrbyDgstfnStatsNewDetailList1 - 김해룡 */
SELECT AA.CN AS CN, --만족도항목 NVL(BB.MCNT,0) + NVL(BB.FCNT,0) AS TCNT, --응답건수(토탈) NVL(BB.MCNT,0) AS MCNT, --응답건수(남) NVL(BB.FCNT,0) AS FCNT, --응답건수(여) NVL(BB.MCNT1,0) + NVL(BB.FCNT1,0) AS TCNT1, --1점(토탈) NVL(BB.MCNT1,0) AS MCNT1, --1점(남) NVL(BB.FCNT1,0) AS FCNT1, --1점(여) NVL(BB.MCNT2,0) + NVL(BB.FCNT2,0) AS TCNT2, --2점(토탈) NVL(BB.MCNT2,0) AS MCNT2, --2점(남) NVL(BB.FCNT2,0) AS FCNT2, --2점(여) NVL(BB.MCNT3,0) + NVL(BB.FCNT3,0) AS TCNT3, --3점(토탈) NVL(BB.MCNT3,0) AS MCNT3, --3점(남) NVL(BB.FCNT3,0) AS FCNT3, --3점(여) NVL(BB.MCNT4,0) + NVL(BB.FCNT4,0) AS TCNT4, --4점(토탈) NVL(BB.MCNT4,0) AS MCNT4, --4점(남) NVL(BB.FCNT4,0) AS FCNT4, --4점(여) NVL(BB.MCNT5,0) + NVL(BB.FCNT5,0) AS TCNT5, --5점(토탈) NVL(BB.MCNT5,0) AS MCNT5, --5점(남) NVL(BB.FCNT5,0) AS FCNT5, --5점(여) CASE WHEN NVL(BB.MCNT,0) + NVL(BB.FCNT,0) > 0 THEN (NVL(BB.MCNT1,0) + NVL(BB.FCNT1,0) + (NVL(BB.MCNT2,0) + NVL(BB.FCNT2,0)) * 2 + (NVL(BB.MCNT3,0) + NVL(BB.FCNT3,0)) * 3 + (NVL(BB.MCNT4,0) + NVL(BB.FCNT4,0)) * 4 + (NVL(BB.MCNT5,0) + NVL(BB.FCNT5,0)) * 5) / (NVL(BB.MCNT,0) + NVL(BB.FCNT,0)) ELSE 0 END AS TAVG, CASE WHEN NVL(BB.MCNT,0) > 0 THEN (NVL(BB.MCNT1,0) + NVL(BB.MCNT2,0) * 2 + NVL(BB.MCNT3,0) * 3 + NVL(BB.MCNT4,0) * 4 + NVL(BB.MCNT5,0) * 5) / NVL(BB.MCNT,0) ELSE 0 END AS MAVG, CASE WHEN NVL(BB.FCNT,0) > 0 THEN (NVL(BB.FCNT1,0) + NVL(BB.FCNT2,0) * 2 + NVL(BB.FCNT3,0) * 3 + NVL(BB.FCNT4,0) * 4 + NVL(BB.FCNT5,0) * 5) / NVL(BB.FCNT,0) ELSE 0 END AS FAVG
FROM ( SELECT QESITM_ESNTAL_NO NO, QESITM_CN CN FROM AYE197 WHERE TYPE_SE_NM = 'solrobot' ) AA, ( SELECT A.QESITM_ESNTAL_NO NO, SUM(CASE WHEN C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT, SUM(CASE WHEN C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT, SUM(CASE WHEN A.RSPNS_CN = '1' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT1, SUM(CASE WHEN A.RSPNS_CN = '1' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT1, SUM(CASE WHEN A.RSPNS_CN = '2' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT2, SUM(CASE WHEN A.RSPNS_CN = '2' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT2, SUM(CASE WHEN A.RSPNS_CN = '3' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT3, SUM(CASE WHEN A.RSPNS_CN = '3' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT3, SUM(CASE WHEN A.RSPNS_CN = '4' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT4, SUM(CASE WHEN A.RSPNS_CN = '4' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT4, SUM(CASE WHEN A.RSPNS_CN = '5' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT5, SUM(CASE WHEN A.RSPNS_CN = '5' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT5 FROM AYE196 A, AYE195 B, AYE100 C WHERE 1=1 AND A.INDEX_SN =B.INDEX_SN AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' AND C.DEL_YN = 'N' AND B.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT < TO_DATE(#{endDate} || '235959', 'YYYYMMDDHH24MISS') AND B.BBSCTT_ESNTAL_NO =C.BBSCTT_ESNTAL_NO AND B.BBSCTT_TYPE_SE_CD =C.BBSCTT_TYPE_SE_CD AND C.BBSCTT_TYPE_SE_CD IN ( '01', '02') AND C.SLRBT_DSCSN_SCLAS_SE_CD = #{slrbtCD} /* 리스트에서 클릭한 행의 CD SAC100.CMMNS_CD_VALUE */ GROUP BY A.QESITM_ESNTAL_NO ) BB WHERE AA.NO = BB.NO(+)

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectSlrbyDgstfnStatsNewDetailList2 - 김해룡 */
SELECT AA.CN AS CN, --만족도항목 NVL(BB.MCNT,0) + NVL(BB.FCNT,0) AS TCNT, --응답건수(토탈) NVL(BB.MCNT,0) AS MCNT, --응답건수(남) NVL(BB.FCNT,0) AS FCNT, --응답건수(여) NVL(BB.MCNT1,0) + NVL(BB.FCNT1,0) AS TCNT1, --1점(토탈) NVL(BB.MCNT1,0) AS MCNT1, --1점(남) NVL(BB.FCNT1,0) AS FCNT1, --1점(여) NVL(BB.MCNT2,0) + NVL(BB.FCNT2,0) AS TCNT2, --2점(토탈) NVL(BB.MCNT2,0) AS MCNT2, --2점(남) NVL(BB.FCNT2,0) AS FCNT2, --2점(여) NVL(BB.MCNT3,0) + NVL(BB.FCNT3,0) AS TCNT3, --3점(토탈) NVL(BB.MCNT3,0) AS MCNT3, --3점(남) NVL(BB.FCNT3,0) AS FCNT3, --3점(여) NVL(BB.MCNT4,0) + NVL(BB.FCNT4,0) AS TCNT4, --4점(토탈) NVL(BB.MCNT4,0) AS MCNT4, --4점(남) NVL(BB.FCNT4,0) AS FCNT4, --4점(여) NVL(BB.MCNT5,0) + NVL(BB.FCNT5,0) AS TCNT5, --5점(토탈) NVL(BB.MCNT5,0) AS MCNT5, --5점(남) NVL(BB.FCNT5,0) AS FCNT5, --5점(여) CASE WHEN NVL(BB.MCNT,0) + NVL(BB.FCNT,0) > 0 THEN (NVL(BB.MCNT1,0) + NVL(BB.FCNT1,0) + (NVL(BB.MCNT2,0) + NVL(BB.FCNT2,0)) * 2 + (NVL(BB.MCNT3,0) + NVL(BB.FCNT3,0)) * 3 + (NVL(BB.MCNT4,0) + NVL(BB.FCNT4,0)) * 4 + (NVL(BB.MCNT5,0) + NVL(BB.FCNT5,0)) * 5) / (NVL(BB.MCNT,0) + NVL(BB.FCNT,0)) ELSE 0 END AS TAVG, CASE WHEN NVL(BB.MCNT,0) > 0 THEN (NVL(BB.MCNT1,0) + NVL(BB.MCNT2,0) * 2 + NVL(BB.MCNT3,0) * 3 + NVL(BB.MCNT4,0) * 4 + NVL(BB.MCNT5,0) * 5) / NVL(BB.MCNT,0) ELSE 0 END AS MAVG, CASE WHEN NVL(BB.FCNT,0) > 0 THEN (NVL(BB.FCNT1,0) + NVL(BB.FCNT2,0) * 2 + NVL(BB.FCNT3,0) * 3 + NVL(BB.FCNT4,0) * 4 + NVL(BB.FCNT5,0) * 5) / NVL(BB.FCNT,0) ELSE 0 END AS FAVG
FROM ( SELECT QESITM_ESNTAL_NO NO, QESITM_CN CN FROM AYE197 WHERE TYPE_SE_NM = 'solrobot' ) AA, ( SELECT A.QESITM_ESNTAL_NO NO, SUM(CASE WHEN C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT, SUM(CASE WHEN C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT, SUM(CASE WHEN A.RSPNS_CN = '1' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT1, SUM(CASE WHEN A.RSPNS_CN = '1' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT1, SUM(CASE WHEN A.RSPNS_CN = '2' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT2, SUM(CASE WHEN A.RSPNS_CN = '2' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT2, SUM(CASE WHEN A.RSPNS_CN = '3' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT3, SUM(CASE WHEN A.RSPNS_CN = '3' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT3, SUM(CASE WHEN A.RSPNS_CN = '4' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT4, SUM(CASE WHEN A.RSPNS_CN = '4' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT4, SUM(CASE WHEN A.RSPNS_CN = '5' AND C.SXDC_SE_CD = 'M' THEN 1 ELSE 0 END ) MCNT5, SUM(CASE WHEN A.RSPNS_CN = '5' AND C.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END ) FCNT5 FROM AYE196 A, AYE195 B, AYE100 C WHERE 1=1 AND A.INDEX_SN =B.INDEX_SN AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' AND C.DEL_YN = 'N' AND B.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT < TO_DATE(#{endDate} || '235959', 'YYYYMMDDHH24MISS') AND B.BBSCTT_ESNTAL_NO =C.BBSCTT_ESNTAL_NO AND B.BBSCTT_TYPE_SE_CD =C.BBSCTT_TYPE_SE_CD AND C.BBSCTT_TYPE_SE_CD IN ( '01', '02') AND C.SLRBT_DSCSN_SCLAS_SE_CD = #{slrbtCD} /* 리스트에서 클릭한 행의 CD SAC100.CMMNS_CD_VALUE */ GROUP BY A.QESITM_ESNTAL_NO ) BB WHERE AA.NO = BB.NO(+)

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectGriefSltnAlkiolDgstfnStatsDetailList - 응용2팀 지원 정원제 */ SELECT AA.NO AS NO, /* 문항번호*/ AA.CN AS CN, /* 문항내용*/ BB.CNT1 AS CNT1, /* 1점건수 */ BB.CNT2 AS CNT2, /* 2점건수 */ BB.CNT3 AS CNT3, /* 3점건수 */ BB.CNT4 AS CNT4, /* 4점건수 */ BB.CNT5 AS CNT5, /* 5점건수 */
CASE WHEN (CNT1 + CNT2 + CNT3 + CNT4 + CNT5) > 0 THEN (CNT1 + CNT2*2 + CNT3*3 + CNT4*4 + CNT5*5)/(CNT1 + CNT2 + CNT3 + CNT4 + CNT5) ELSE 0 END AS AVER /* 평균만족도 */
FROM ( SELECT QESITM_ESNTAL_NO AS NO, /* 문항번호 */ QESITM_CN AS CN /* 문항내용 */ FROM AYE197 WHERE 1=1 AND TYPE_SE_NM = 'gomin' ) AA, ( SELECT C.QESITM_ESNTAL_NO AS NO, NVL(SUM(CASE WHEN C.RSPNS_CN = '1' THEN 1 ELSE 0 END),0) AS CNT1, /* 1점건수 */ NVL(SUM(CASE WHEN C.RSPNS_CN = '2' THEN 1 ELSE 0 END),0) AS CNT2, /* 2점건수 */ NVL(SUM(CASE WHEN C.RSPNS_CN = '3' THEN 1 ELSE 0 END),0) AS CNT3, /* 3점건수 */ NVL(SUM(CASE WHEN C.RSPNS_CN = '4' THEN 1 ELSE 0 END),0) AS CNT4, /* 4점건수 */ NVL(SUM(CASE WHEN C.RSPNS_CN = '5' THEN 1 ELSE 0 END),0) AS CNT5 /* 5점건수 */ FROM AYE100 A , AYE195 B , AYE196 C WHERE 1=1 AND A.GRIEF_SLTN_ALKIOL_SN = #{griefSltnAlkiolSn} AND A.BBSCTT_ESNTAL_NO = B.BBSCTT_ESNTAL_NO AND A.BBSCTT_TYPE_SE_CD = B.BBSCTT_TYPE_SE_CD AND B.BBSCTT_TYPE_SE_CD = #{bbscttTypeSeCd}
AND B.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT <= TO_DATE(#{endDate} || '000000', 'YYYYMMDDHH24MISS')
AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' AND C.INDEX_SN = B.INDEX_SN AND C.DEL_YN = 'N' GROUP BY C.QESITM_ESNTAL_NO ) BB WHERE AA.NO = BB.NO(+) ORDER BY AA.NO

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectConsttSrvyStatsList - 김해룡 */ WITH USER1 AS ( SELECT A.USER_ID ID,--아이디 B.ENFSN_NO NO,--종사자번호 C##RG.DEC_B64(B.FLNM_ENCPT) NM,--상담원성명 B.OGDP_DEPT_CD CD --부서코드 FROM SAA200 A ,SCA100 B WHERE 1=1 AND A.ENFSN_NO = B.ENFSN_NO AND B.OGDP_INST_NO = '1000000947' --기관번호 AND B.OGDP_DEPT_CD IN ('324','325') --부서코드 ( 324사이버상담, 325사이버아웃리치 326모바일상담(X))
AND b.OGDP_DEPT_CD = #{deptCd}
AND A.USER_ID = #{sUserId} --로그인 유저 아이디
) SELECT CM.ID AS ID, CM.NM AS NM, NVL(AA.CNT01,0) + NVL(BB.CNT01,0) + NVL(CC.CNT01,0) AS CNT01, --01학업중단 NVL(AA.CNT02,0) + NVL(BB.CNT02,0) + NVL(CC.CNT02,0) AS CNT02, --02가출 NVL(AA.CNT03,0) + NVL(BB.CNT03,0) + NVL(CC.CNT03,0) AS CNT03, --03대인관계 NVL(AA.CNT04,0) + NVL(BB.CNT04,0) + NVL(CC.CNT04,0) AS CNT04, --04학업·진로 NVL(AA.CNT05,0) + NVL(BB.CNT05,0) + NVL(CC.CNT05,0) AS CNT05, --05과의존·중독 NVL(AA.CNT06,0) + NVL(BB.CNT06,0) + NVL(CC.CNT06,0) AS CNT06, --06정신건강 NVL(AA.CNT07,0) + NVL(BB.CNT07,0) + NVL(CC.CNT07,0) AS CNT07, --07폭력피해 NVL(AA.CNT08,0) + NVL(BB.CNT08,0) + NVL(CC.CNT08,0) AS CNT08, --08폭력가해·비행 NVL(AA.CNT09,0) + NVL(BB.CNT09,0) + NVL(CC.CNT09,0) AS CNT09, --09성 NVL(AA.CNT10,0) + NVL(BB.CNT10,0) + NVL(CC.CNT10,0) AS CNT10, --10노동·근로 NVL(AA.CNT11,0) + NVL(BB.CNT11,0) + NVL(CC.CNT11,0) AS CNT11, --11결핍·빈곤 NVL(AA.CNT12,0) + NVL(BB.CNT12,0) + NVL(CC.CNT12,0) AS CNT12, --12신체건강·인식 NVL(AA.CNT13,0) + NVL(BB.CNT13,0) + NVL(CC.CNT13,0) AS CNT13, --13한국문화적응·체류 NVL(AA.CNT14,0) + NVL(BB.CNT14,0) + NVL(CC.CNT14,0) AS CNT14, --14법적처분 NVL(AA.CNT99,0) + NVL(BB.CNT99,0) + NVL(CC.CNT99,0) AS CNT99, --99기타(텍스트 입력) NVL(AA.CNTXX,0) + NVL(BB.CNTXX,0) + NVL(CC.CNTXX,0) AS CNTXX --미확인 FROM USER1 CM, ( SELECT A.CNSLTNT_ID ID, --상담원아이디 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '01' THEN 1 ELSE 0 END) CNT01, --01학업중단 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '02' THEN 1 ELSE 0 END) CNT02, --02가출 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '03' THEN 1 ELSE 0 END) CNT03, --03대인관계 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '04' THEN 1 ELSE 0 END) CNT04, --04학업·진로 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '05' THEN 1 ELSE 0 END) CNT05, --05과의존·중독 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '06' THEN 1 ELSE 0 END) CNT06, --06정신건강 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '07' THEN 1 ELSE 0 END) CNT07, --07폭력피해 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '08' THEN 1 ELSE 0 END) CNT08, --08폭력가해·비행 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '09' THEN 1 ELSE 0 END) CNT09, --09성 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '10' THEN 1 ELSE 0 END) CNT10, --10노동·근로 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '11' THEN 1 ELSE 0 END) CNT11, --11결핍·빈곤 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '12' THEN 1 ELSE 0 END) CNT12, --12신체건강·인식 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '13' THEN 1 ELSE 0 END) CNT13, --13한국문화적응·체류 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '14' THEN 1 ELSE 0 END) CNT14, --14법적처분 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '99' THEN 1 ELSE 0 END) CNT99, --99기타(텍스트 입력) SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD is null THEN 1 ELSE 0 END) CNTXX --미확인 FROM AYB200 A, USER1 B, AYE195 C WHERE 1=1 AND A.DEL_YN = 'N'
AND A.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{endDate} || '235959', 'YYYYMMDDHH24MISS')
AND A.CNSLTNT_ID = B.ID AND A.CHRO_NO = C.BBSCTT_ESNTAL_NO AND C.BBSCTT_TYPE_SE_CD = '24' GROUP BY A.CNSLTNT_ID ) AA, ( SELECT A.FRST_RGTR_ID ID, --상담원아이디 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '01' THEN 1 ELSE 0 END) CNT01, --01학업중단 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '02' THEN 1 ELSE 0 END) CNT02, --02가출 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '03' THEN 1 ELSE 0 END) CNT03, --03대인관계 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '04' THEN 1 ELSE 0 END) CNT04, --04학업·진로 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '05' THEN 1 ELSE 0 END) CNT05, --05과의존·중독 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '06' THEN 1 ELSE 0 END) CNT06, --06정신건강 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '07' THEN 1 ELSE 0 END) CNT07, --07폭력피해 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '08' THEN 1 ELSE 0 END) CNT08, --08폭력가해·비행 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '09' THEN 1 ELSE 0 END) CNT09, --09성 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '10' THEN 1 ELSE 0 END) CNT10, --10노동·근로 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '11' THEN 1 ELSE 0 END) CNT11, --11결핍·빈곤 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '12' THEN 1 ELSE 0 END) CNT12, --12신체건강·인식 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '13' THEN 1 ELSE 0 END) CNT13, --13한국문화적응·체류 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '14' THEN 1 ELSE 0 END) CNT14, --14법적처분 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '99' THEN 1 ELSE 0 END) CNT99, --99기타(텍스트 입력) SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD is null THEN 1 ELSE 0 END) CNTXX --미확인 FROM AYE100 A, USER1 B, AYE195 C WHERE 1=1 AND A.DEL_YN = 'N'
AND A.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{endDate} || '235959', 'YYYYMMDDHH24MISS')
AND A.FRST_RGTR_ID = B.ID AND A.BBSCTT_ESNTAL_NO = C.BBSCTT_ESNTAL_NO AND A.BBSCTT_TYPE_SE_CD = C.BBSCTT_TYPE_SE_CD GROUP BY A.FRST_RGTR_ID ) BB, ( SELECT A.FRST_RGTR_ID ID, --상담원아이디 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '01' THEN 1 ELSE 0 END) CNT01, --01학업중단 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '02' THEN 1 ELSE 0 END) CNT02, --02가출 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '03' THEN 1 ELSE 0 END) CNT03, --03대인관계 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '04' THEN 1 ELSE 0 END) CNT04, --04학업·진로 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '05' THEN 1 ELSE 0 END) CNT05, --05과의존·중독 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '06' THEN 1 ELSE 0 END) CNT06, --06정신건강 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '07' THEN 1 ELSE 0 END) CNT07, --07폭력피해 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '08' THEN 1 ELSE 0 END) CNT08, --08폭력가해·비행 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '09' THEN 1 ELSE 0 END) CNT09, --09성 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '10' THEN 1 ELSE 0 END) CNT10, --10노동·근로 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '11' THEN 1 ELSE 0 END) CNT11, --11결핍·빈곤 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '12' THEN 1 ELSE 0 END) CNT12, --12신체건강·인식 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '13' THEN 1 ELSE 0 END) CNT13, --13한국문화적응·체류 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '14' THEN 1 ELSE 0 END) CNT14, --14법적처분 SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD = '99' THEN 1 ELSE 0 END) CNT99, --99기타(텍스트 입력) SUM(CASE WHEN A.PROBM_STTS_LCLAS_SE_CD is null THEN 1 ELSE 0 END) CNTXX --미확인 FROM AYE100 A, USER1 B, AYE260 C WHERE 1=1 AND A.DEL_YN = 'N'
AND A.FRST_REG_DT >= TO_DATE(#{startDate} || '000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{endDate} || '235959', 'YYYYMMDDHH24MISS')
AND A.FRST_RGTR_ID = B.ID AND A.BBSCTT_ESNTAL_NO = C.BBSCTT_ESNTAL_NO AND A.BBSCTT_TYPE_SE_CD = C.BBSCTT_TYPE_SE_CD GROUP BY A.FRST_RGTR_ID ) CC WHERE CM.ID = AA.ID(+) AND CM.ID = BB.ID(+) AND CM.ID = CC.ID(+)

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper.selectConsttSrvyStatsList1 - 개발지원팀 이태호 */ SELECT REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE1+SCORE2+SCORE3+SCORE4+SCORE5+SCORE6+SCORE7+SCORE8+SCORE9+SCORE10+SCORE11+SCORE12)), '(\d{3})', '\1,')), '^,', '') AS TOTAL_SCORE , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT1 + CNT2 + CNT3 + CNT4 + CNT5 + CNT6 + CNT7 + CNT8 + CNT9 + CNT10 + CNT11 + CNT12)), '(\d{3})', '\1,')), '^,', '') AS TOTAL_CNT , FLNM AS FLNM , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT1)), '(\d{3})', '\1,')), '^,', '') AS CNT1 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT2)), '(\d{3})', '\1,')), '^,', '') AS CNT2 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT3)), '(\d{3})', '\1,')), '^,', '') AS CNT3 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT4)), '(\d{3})', '\1,')), '^,', '') AS CNT4 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT5)), '(\d{3})', '\1,')), '^,', '') AS CNT5 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT6)), '(\d{3})', '\1,')), '^,', '') AS CNT6 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT7)), '(\d{3})', '\1,')), '^,', '') AS CNT7 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT8)), '(\d{3})', '\1,')), '^,', '') AS CNT8 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT9)), '(\d{3})', '\1,')), '^,', '') AS CNT9 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT10)), '(\d{3})', '\1,')), '^,', '') AS CNT10 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT11)), '(\d{3})', '\1,')), '^,', '') AS CNT11 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(CNT12)), '(\d{3})', '\1,')), '^,', '') AS CNT12 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE1)), '(\d{3})', '\1,')), '^,', '') AS SCORE1 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE2)), '(\d{3})', '\1,')), '^,', '') AS SCORE2 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE3)), '(\d{3})', '\1,')), '^,', '') AS SCORE3 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE4)), '(\d{3})', '\1,')), '^,', '') AS SCORE4 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE5)), '(\d{3})', '\1,')), '^,', '') AS SCORE5 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE6)), '(\d{3})', '\1,')), '^,', '') AS SCORE6 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE7)), '(\d{3})', '\1,')), '^,', '') AS SCORE7 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE8)), '(\d{3})', '\1,')), '^,', '') AS SCORE8 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE9)), '(\d{3})', '\1,')), '^,', '') AS SCORE9 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE10)), '(\d{3})', '\1,')), '^,', '') AS SCORE10 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE11)), '(\d{3})', '\1,')), '^,', '') AS SCORE11 , REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(SCORE12)), '(\d{3})', '\1,')), '^,', '') AS SCORE12 FROM(
SELECT FLNM ,CNT1 ,CNT2 ,CNT3 ,CNT4 ,CNT5 ,CNT6 ,CNT7 ,CNT8 ,CNT9 ,CNT10 ,CNT11 ,CNT12 ,CASE WHEN CNT1 != 0 THEN RSPNS_CN / CNT1 ELSE 0 END AS SCORE1 ,CASE WHEN CNT2 != 0 THEN RSPNS_CN / CNT2 ELSE 0 END AS SCORE2 ,CASE WHEN CNT3 != 0 THEN RSPNS_CN / CNT3 ELSE 0 END AS SCORE3 ,CASE WHEN CNT4 != 0 THEN RSPNS_CN / CNT4 ELSE 0 END AS SCORE4 ,CASE WHEN CNT5 != 0 THEN RSPNS_CN / CNT5 ELSE 0 END AS SCORE5 ,CASE WHEN CNT6 != 0 THEN RSPNS_CN / CNT6 ELSE 0 END AS SCORE6 ,CASE WHEN CNT7 != 0 THEN RSPNS_CN / CNT7 ELSE 0 END AS SCORE7 ,CASE WHEN CNT8 != 0 THEN RSPNS_CN / CNT8 ELSE 0 END AS SCORE8 ,CASE WHEN CNT9 != 0 THEN RSPNS_CN / CNT9 ELSE 0 END AS SCORE9 ,CASE WHEN CNT10 != 0 THEN RSPNS_CN / CNT10 ELSE 0 END AS SCORE10 ,CASE WHEN CNT11 != 0 THEN RSPNS_CN / CNT11 ELSE 0 END AS SCORE11 ,CASE WHEN CNT12 != 0 THEN RSPNS_CN / CNT12 ELSE 0 END AS SCORE12 FROM( WITH AA10 AS( SELECT a.USER_ID AS USER_ID , b.FLNM_ENCPT AS FLNM FROM SAA200 a /* 사용자 */ , SCA100 b /* 종사자 */ WHERE 1=1 AND a.ENFSN_NO = b.ENFSN_NO
AND b.OGDP_DEPT_CD = #{deptCd}
) SELECT T.FLNM ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '01' THEN 1 ELSE 0 END), 0) AS CNT1 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '02' THEN 1 ELSE 0 END), 0) AS CNT2 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '03' THEN 1 ELSE 0 END), 0) AS CNT3 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '04' THEN 1 ELSE 0 END), 0) AS CNT4 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '05' THEN 1 ELSE 0 END), 0) AS CNT5 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '06' THEN 1 ELSE 0 END), 0) AS CNT6 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '07' THEN 1 ELSE 0 END), 0) AS CNT7 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '08' THEN 1 ELSE 0 END), 0) AS CNT8 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '09' THEN 1 ELSE 0 END), 0) AS CNT9 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '10' THEN 1 ELSE 0 END), 0) AS CNT10 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '11' THEN 1 ELSE 0 END), 0) AS CNT11 ,NVL(SUM(CASE WHEN a.PROBM_STTS_LCLAS_SE_CD = '99' THEN 1 ELSE 0 END), 0) AS CNT12 ,sum(c.RSPNS_CN) AS RSPNS_CN FROM AA10 T ,AYE120 a /* 사이버상담답글 */ ,AYE195 b /* 상담글평가 */ ,AYE196 c /* 설문응답내용 */ WHERE 1=1 AND T.USER_ID = a.FRST_RGTR_ID AND a.BBSCTT_ESNTAL_NO = b.BBSCTT_ESNTAL_NO AND a.BBSCTT_TYPE_SE_CD = b.BBSCTT_TYPE_SE_CD --게시글유형코드 AND b.INDEX_SN = c.INDEX_SN AND a.PROBM_STTS_LCLAS_SE_CD IS NOT NULL AND a.DEL_YN = 'N' AND b.DEL_YN = 'N' AND c.DEL_YN = 'N' AND a.FRST_REG_DT BETWEEN #{startDate} AND #{endDate} AND T.USER_ID = #{sUserId} GROUP BY T.FLNM ) )

/* isry.couns.stats.dscsnstats.mapper.ConQuestionStatsMapper."selectInstList" - 월별*기관별 실적 */ WITH Z1 AS (
) SELECT /* SQL-ID : 월별*기관별 실적 */ EE.* FROM ( SELECT * FROM Z1 PIVOT ( SUM( CCNT ) FOR YYYYMM IN
'${item}' AS ${item}
) ) EE WHERE 1=1 ORDER BY SQNCE
